package com.meetspace.controller; import com.meetspace.dto.*; import com.meetspace.dto.RoomDtos.*; import com.meetspace.service.RoomService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController public class RoomController{private final RoomService s;public RoomController(RoomService s){this.s=s;}@GetMapping("/api/rooms") ApiResponse<List<Room>> list(){return ApiResponse.ok("Rooms retrieved",s.list());}@GetMapping("/api/rooms/{id}") ApiResponse<Room> get(@PathVariable UUID id){return ApiResponse.ok("Room retrieved",s.get(id));}@PostMapping("/api/admin/rooms") ResponseEntity<ApiResponse<Room>> create(@Valid @RequestBody Save x){return ResponseEntity.status(201).body(ApiResponse.ok("Room created",s.create(x)));}@PutMapping("/api/admin/rooms/{id}") ApiResponse<Room> update(@PathVariable UUID id,@Valid @RequestBody Save x){return ApiResponse.ok("Room updated",s.update(id,x));}@DeleteMapping("/api/admin/rooms/{id}") ResponseEntity<ApiResponse<Void>> delete(@PathVariable UUID id){s.deactivate(id);return ResponseEntity.status(HttpStatus.NO_CONTENT).body(ApiResponse.ok("Room deactivated",null));}}